598	\section{Typed conditionally linear distributions}
599	% Paper section label sec:types kept for cross-reference fidelity. Only the mathematical
600	% typed material (typed CL functions and distributions, graph distributions) is stated
601	% here; the typed sampler and verifier machinery of the source is outside the scope of
602	% the mathematical development.
603	\label{sec:types}
604	
605	The question distribution of the Pauli basis test is \emph{typed}: each question is a pair consisting of a type, drawn together with the other player's type from the edges of a fixed \emph{type graph}, and a question content, drawn from a CL distribution determined by the pair of types.
606	
607	\begin{definition}[Typed conditionally linear functions]\label{def:typed-cl-functions}
608		\lean{MIPStarRE.QPBT.IsTypedCondLinearFamily}
609		\leanok
610		\uses{def:cl-func}
611		Let $\mathcal T$ be a finite set (the \emph{type set}) and let $V$ be $\F^n$ for some integer $n \ge 0$. A \emph{$\mathcal T$-typed family of $\ell$-level conditionally linear functions} (implicitly, \emph{on $V$}) is a collection $\{L_t\}_{t \in \mathcal T}$ such that, for each $t \in \mathcal T$, $L_t$ is an $\ell$-level conditionally linear function on $V$.
612	\end{definition}
613	
614	% Nonemptiness of the edge set is stated explicitly here: with E empty, m = k = 0 and the
615	% normalization 1/(2m-k) below is undefined. The source
616	% (references/qpbt-paper/07_types.tex:65-82) leaves this boundary hypothesis implicit.
617	\begin{definition}[Graph distribution]\label{def:graph-distribution}
618		\lean{MIPStarRE.QPBT.graphDistribution, MIPStarRE.QPBT.graphDistribution_isProbability}
619		\leanok
620		Let $G = (U, E)$ be an undirected graph with vertex set $U$ and nonempty edge set $E$. Edges in $E$ are written as multisets $\{u, v\}$ of two vertices; the case $u = v$ represents a self-loop. Suppose there are $m \ge 1$ edges, $k$ of which are self-loops. Then the \emph{graph distribution $\mu_G$ of $G$} is the distribution over $U \times U$ such that for every $(u,v) \in U \times U$,
621		\[
622			\mu_G(u, v) =
623			\begin{cases}
624				1/(2m-k) & \text{if } \{u,v\} \in E\,,\\
625				0 & \text{otherwise}\,.
626			\end{cases}
627		\]
628		This is identical to the uniform distribution over ordered pairs $(u,v) \in U \times U$ such that $\{u,v\} \in E$: each edge that is not a self-loop contributes two ordered pairs, and each self-loop contributes one, whence the normalization $2m-k$.
629	\end{definition}
630	
